import{_ as a,H as p,f as t,i}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"20 | 用户行为分析：最高价值密度的数据决策洞察","description":"","frontmatter":{},"headers":[{"level":2,"title":"过去几年发展最快的特定领域分析产品","slug":"过去几年发展最快的特定领域分析产品","link":"#过去几年发展最快的特定领域分析产品","children":[]},{"level":2,"title":"用户行为分析的作用","slug":"用户行为分析的作用","link":"#用户行为分析的作用","children":[]},{"level":2,"title":"从头开始搭建一个用户行为分析系统","slug":"从头开始搭建一个用户行为分析系统","link":"#从头开始搭建一个用户行为分析系统","children":[{"level":3,"title":"典型架构设计","slug":"典型架构设计","link":"#典型架构设计","children":[]},{"level":3,"title":"数据模型与 ETL","slug":"数据模型与-etl","link":"#数据模型与-etl","children":[]},{"level":3,"title":"分析模型抽象","slug":"分析模型抽象","link":"#分析模型抽象","children":[]}]},{"level":2,"title":"曾经踩过的坑","slug":"曾经踩过的坑","link":"#曾经踩过的坑","children":[{"level":3,"title":"流量突增与数据积压的处理策略","slug":"流量突增与数据积压的处理策略","link":"#流量突增与数据积压的处理策略","children":[]},{"level":3,"title":"查询积压","slug":"查询积压","link":"#查询积压","children":[]},{"level":3,"title":"国际化的应对","slug":"国际化的应对","link":"#国际化的应对","children":[]}]},{"level":2,"title":"局限","slug":"局限","link":"#局限","children":[]},{"level":2,"title":"总结与启发","slug":"总结与启发","link":"#总结与启发","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"大数据应用实战/20｜用户行为分析：最高价值密度的数据决策洞察.md","filePath":"大数据应用实战/20｜用户行为分析：最高价值密度的数据决策洞察.md","lastUpdated":1795555553000}'),n={name:"大数据应用实战/20｜用户行为分析：最高价值密度的数据决策洞察.md"};function s(l,e,r,o,h,E){return p(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="_20-用户行为分析-最高价值密度的数据决策洞察" tabindex="-1">20 | 用户行为分析：最高价值密度的数据决策洞察 <a class="header-anchor" href="#_20-用户行为分析-最高价值密度的数据决策洞察" aria-label="Permalink to &quot;20 | 用户行为分析：最高价值密度的数据决策洞察&quot;">​</a></h1><p>你好，我是曹犟。</p><p>在上一节课中，我们讨论了 BI，一种通用数据分析产品。正如上节课中所提到的，它虽然可以覆盖绝大部分的数据分析需求，但是在我们日常的工程实践中，很多时候针对一些特定领域的分析需求，依然会开发一些专门的分析产品，来为客户提供更好的分析体验。在这节课中，我们主要讨论用户行为分析这个特定领域。</p><h2 id="过去几年发展最快的特定领域分析产品" tabindex="-1">过去几年发展最快的特定领域分析产品 <a class="header-anchor" href="#过去几年发展最快的特定领域分析产品" aria-label="Permalink to &quot;过去几年发展最快的特定领域分析产品&quot;">​</a></h2><p>首先，我们需要先大概了解什么是用户行为分析，以及我们为什么要做用户行为分析。</p><p>所谓的用户行为分析，简称 UBA（User Behavior Analytics），是指收集、整理、分析用户在产品（如 App、网站、小程序、智能终端等）中的各种交互数据，从而找到用户的行为规律、需求偏好、产品改进点等。</p><p>在过去相当长一段时间内，用户行为分析是发展最快的特定领域分析产品了。最早的用户行为分析产品，有国外的 Google Analytics，国内的百度统计、友盟，他们当时主要以固定的数据采集和固定的报表为主。随后，在国外出现了 Mixpanel、Amplitude、PostHog 等产品，国内也有神策分析。这些后出现的新一代分析产品，则以更加灵活的数据采集和分析能力著称，里面也出现了不少独角兽和上市公司。</p><p>我们先来讨论一下，用户行为分析到底能带来哪些实际的业务收益，才能够创造这么多商业价值。</p><h2 id="用户行为分析的作用" tabindex="-1">用户行为分析的作用 <a class="header-anchor" href="#用户行为分析的作用" aria-label="Permalink to &quot;用户行为分析的作用&quot;">​</a></h2><p>我们花费硬件和人力成本，去采集用户行为数据，除了在类似于风控、推荐等实时业务数据流中作为重要的数据源之外，分析这些用户行为本身也有助于我们做出产品改进、投放改进、用户洞察等重要的业务洞察和决策。</p><p>而用户行为分析领域之所以在过去几年发展迅速，也是因为在这个用户精细化越来越重要的时代，用户行为数据本身也是价值密度最高的一类数据了。</p><p>我们看几个具体的应用场景，来帮助你理解。</p><p>在产品设计方面，每一个产品经理都对于用户应该如何使用自己的产品会有一个大致的预期。例如，对于“某出海挖掘机制造商的西班牙语官网”这么一个产品，用户通常通过搜索引擎进入到官网首页，然后点击一些自己感兴趣的挖掘机产品的介绍，觉得这些产品对自己有用之后，就在官网上通过表单留下自己的联系方式，从而形成一个完整的“留资”路径。</p><p>对于官网的产品经理和开发人员，就可以具体分析这些用户的使用路径，包括访问页面的先后顺序、每个页面的停留时间、退出页面、填写表单每个步骤的时间等。</p><p>通过这些分析，他们可以回答下面的问题：</p><ul><li><p>哪些页面还不够吸引用户？</p></li><li><p>表单的设计是否有障碍？</p></li><li><p>页面的布局应该如何调整？</p></li><li><p>……</p></li></ul><p>同时，很多现代用户行为分析产品还提供 Session Replay 功能。它能以类似于录像的方式回放用户的具体操作。产品经理就相当于“站在用户背后”看用户是如何使用自己的产品的。对于一个希望持续改进自己产品设计的产品经理，这类分析和洞察十分重要，甚至是必不可少的。</p><p>在投放改进领域，负责投放的投手，也需要使用用户行为分析产品。投手需要衡量不同媒体、不同关键词、不同素材的投放计划，分别进来了多少用户。需要了解这些用户有多大比例完成了转化购买，30 天留存比例是多少。通过这些数据，投手可以计算出一个用户的 LTV（全生命周期价值），而我们又可以通过媒体的 API，来得到每一个用户的购买价格。有了这两部分数据，衡量投放的 ROI，并且根据 ROI 调整投放策略就变得非常简单了。</p><p>在用户洞察领域，负责精细化运营的用户运营岗位，可以通过分析、统计用户的行为，例如，用户过去 30 天的付费金额，过去 30 天的访问频率，来给每一个用户打上不同的标签，并基于标签构建不同的用户分群，在 CDP 系统（第 21、22 节课程会涉及）中进行管理。对不同分群的用户行为进行更细粒度的分析对比，可以得到更深入的洞察。同时，分群也作为数据来源导出到智能运营和媒体的投放平台中，实现更精细化的触达。</p><p>刚才我分享了三个实际的场景，帮助你认识用户行为分析的典型价值。既然具有这么大的价值，除了购买专业的产品之外，我们可以自己从头搭建一个用户行为分析系统吗？</p><p>幸运的是，随着类似于 Doris、ClickHouse 这样的开源 OLAP 数据库的蓬勃发展，技术的门槛大大降低，增加了自建的可能性。</p><h2 id="从头开始搭建一个用户行为分析系统" tabindex="-1">从头开始搭建一个用户行为分析系统 <a class="header-anchor" href="#从头开始搭建一个用户行为分析系统" aria-label="Permalink to &quot;从头开始搭建一个用户行为分析系统&quot;">​</a></h2><p>接下来，我们一起看看怎么样基于各种开源方案，来低成本从头搭建一个实时的用户行为分析系统。</p><h3 id="典型架构设计" tabindex="-1">典型架构设计 <a class="header-anchor" href="#典型架构设计" aria-label="Permalink to &quot;典型架构设计&quot;">​</a></h3><p>我们先从数据流的角度，来描述一个典型的用户行为分析系统的架构设计。</p><p>下面是一个最典型的架构图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/20/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/20/1.png" alt=""></a></p><p>在数据采集方面，正如第 3 节课中描述的那样，我们可以使用神策数据开源的各种客户端SDK，进行客户端埋点，采集用户行为和用户属性。埋点时以自动化埋点为主，对于一些必要的属性和事件，采用自定义代码埋点的方式，进行个性化补充。SDK 会自动做好本地缓存和网络传输，尽量保证数据不丢不重。</p><p>当然，对于一些在客户端难以采集的行为和属性，或者一些对于准确率要求非常高的行为，可以在服务端采集日志，或者是直接从业务数据库进行同步，这些你同样可以回顾第 3 节课。</p><p>客户端 SDK 采集的数据，建议使用 HTTPS 协议，将数据压缩后传输到我们架设的数据接收服务。如第 4 节课中所描述的那样，可以使用 Flunted 来接收 HTTPS 请求，并将请求中的有效信息写入到 Kafka 中。</p><p>在实际的应用中，Nginx 等 WebServer 之前，一般会有一层负载均衡服务。一般的公有云都有非常成熟的这类服务提供，选用即可。</p><p>我们选择用 Kafka 作为整个实时行为流的核心载体。数据写入到 Kafka 之后，除了后续的行为分析可以使用之外，其余的如风控、推荐等应用，也可以从 Kafka 订阅数据，满足后续的实时应用需要。</p><p>Apache Doris 为存储和查询模块，提供了一种非常好的存算一体方案。在 Kafka 之后，我们可以自己开发一个 Loader 模块，或者直接启动一个常驻的 Flink 任务，从 Kafka 实时订阅数据流，在完成必要的 ETL 之后，调用 Doris 的 Steam Load API，将数据实时写入到 Doris中。ETL 任务的具体细节我们稍后讨论。</p><p>Doris 中存储的数据，我们可以采用它默认的列存储文件格式，使用默认的 LZ4 压缩格式即可。也可以使用 ZSTD 作为压缩格式，在占用更多 CPU 的同时提供更好的压缩比。</p><p>这是一个非常简单，但是也具有代表性的用户行为分析的架构设计。在这个架构的几个核心模块，如 Fluentd、Kafka、Doris 都具有相当好的水平扩展性。对于不同的数据规模，从每天几十万条到每天几百亿条，这个架构都可以适配。同时，在我们实际的工程实践中，从 SDK 发送数据到写入 Doris 可以被查到，这一时效性延迟也可以很好地保持在 10 秒以内，能够满足绝大部分分析应用的需要。</p><p>数据写入到 Doris 之后，我们就可以开发具体的产品界面，然后让用户通过浏览器来查询实时写入到 Doris 中的数据了，我们后面再具体展开。</p><h3 id="数据模型与-etl" tabindex="-1">数据模型与 ETL <a class="header-anchor" href="#数据模型与-etl" aria-label="Permalink to &quot;数据模型与 ETL&quot;">​</a></h3><p>我们在第 12 节课介绍过 Event-User 模型，它在用户类数据中被广泛使用。在数据写入Doris 之前，有一个关键步骤不能省略，那就是 ETL 处理。我们需要把 SDK 采集来的原始数据，从 Kafka 中读取出来，然后转换成符合 Event-User 模型定义的标准格式。只有这样，数据才能直接用于后续分析。这个环节看起来简单，实际上却是保证数据质量和分析准确性的关键所在。</p><p>在用户行为分析系统中，ETL 环节主要包含以下几类核心工作。</p><p>字段映射与类型转换。客户端 SDK 采集的原始数据字段，需要映射到 Doris 中 Event 表和</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User 表定义好的字段上。例如，SDK 中的 $lib_version 需要映射到 Event 表的</span></span>
<span class="line"><span>sdk_version 字段，同时还需要处理数据类型的转换，比如将字符串类型的时间戳转换为</span></span></code></pre></div><p>Doris 的 DateTime 类型。</p><p>字段扩展与派生。这是用户行为分析中非常重要的一环。基于 IP 地址字段，我们可以通过 IP地址库得到用户的国家、省份、城市等地理位置信息；基于 UserAgent 字段，可以解析出操作系统类型、操作系统版本、浏览器类型、浏览器版本、设备品牌、设备型号等信息；基于Referrer 字段，可以解析出流量来源、搜索引擎、搜索关键词等信息。这些派生字段极大地丰富了后续分析的维度。</p><p>数据清洗与标准化。对于用户行为数据，我们需要过滤掉一些明显的脏数据，例如时间戳为 0或者异常值的数据，事件名称为空的数据等。同时，还需要对一些字段进行标准化处理，例如统一时区为 UTC，统一字符编码为 UTF-8，统一布尔值的表示方式等。在实际的实践过程中，脏数据可以会放在 Kafka 的一个特定 Topic 中作为缓存，等待后续的处理。同时，对于脏数据的细致统计，也是整个质量管理体系的重要数据，这方面可以参考 14 节的内容。</p><p>ID-Mapping 是用户行为分析中最核心也是最复杂的 ETL 工作。在实际的业务场景中，同一个用户可能在不同的设备、不同的渠道留下不同的身份标识。例如，未登录时使用匿名 ID（如Cookie ID、设备 ID），登录后则有明确的登录用户 ID。而用户可能在网页端、App 端、小程序端都有行为，每个端都有自己的匿名标识。ID-Mapping 的核心任务，就是将这些分散的 ID关联起来，识别出它们属于同一个真实用户，并且在它们的 Event 条目中，做相应的修改。关于 ID-Mapping 的详细原理和实现方案，你可以参考第 13 节课的相关内容。</p><p>User 表的更新。除了处理 Event 表的数据之外，ETL 还需要负责维护 User 表。与 Event 数据都是 Append 追加写入不同，User 表的数据都是 Upsert 更新。例如，在神策的 SDK 中，会提供一系列 profile 相关的接口，用以完成对 User 表中用户属性的更新。 如下表所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/20/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/20/2.png" alt=""></a></p><p>Item 表的更新与多实体的处理。我们在第 12 课中介绍过，在用户行为分析领域，Event-User模型本身也在逐步扩展，Item 表和多实体的引入满足了更加丰富的分析需求。对于 Item 表，它的更新逻辑基本等同于 User 表，只不过主键从 UserID 变为了 ItemID。而对于多实体，则是需要在每一条记录中，都详细用特定字段描述当前的数据要作用于具体哪个实体域。一般为了考虑兼容性，不做特殊标注的则是最基本的用户实体。</p><p>在技术实现上，这些 ETL 逻辑可以在 Flink 任务中实现。Flink 从 Kafka 订阅用户行为数据流，对每条数据依次完成上述的各种转换和处理，然后通过 Doris 的 Stream Load API 实时写入。对于 IP 地址库、UserAgent 解析库这类外部依赖，可以在 Flink 任务启动时加载到内存中，避免每条数据都要访问外部服务。对于 ID-Mapping 图谱，由于数据量可能较大，建议使用独立的 ID-Mapping 服务。</p><p>值得注意的是，ETL 环节的性能直接影响整个系统的实时性。在我们的实践中，通过合理的并行度设置和资源配置，可以保证 Flink 任务的处理延迟在秒级，配合 Doris 的实时写入能力，实现端到端 10 秒以内的数据可见性。</p><h3 id="分析模型抽象" tabindex="-1">分析模型抽象 <a class="header-anchor" href="#分析模型抽象" aria-label="Permalink to &quot;分析模型抽象&quot;">​</a></h3><p>了解了 ETL 和数据模型之后，我们接下来看一下分析模型抽象应该具体如何来进行，也顺带解释为什么在用户行为分析领域，需要有特化的产品。</p><p>对 User 表和 Event 表的关联分析（部分场景需要加上 Item 表和多实体概念），就是用户行为分析的本质。而用户行为分析系统的产品化核心，主要就是分析模型的抽象。</p><p>分析模型的抽象，就是将常用的分析范式抽象为特定的分析模型，如最常见的事件分析、漏斗分析、留存分析、分布分析、路径分析等，然后完成界面实现。常见的分析模型有十几种，这里面我主要介绍最典型的事件分析和漏斗分析，让大家先对其中的设计思想有一个了解。</p><p>下面四张图，分别是事件分析、漏斗分析这两个分析模型的配置和结果展示的界面，供你参考。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/20/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/20/3.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/20/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/20/4.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/20/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/20/5.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/20/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/20/6.png" alt=""></a></p><p>我们先来看事件分析模型的产品抽象思想。</p><p>事件分析解决的核心问题是——“某个特定行为发生了多少次，是由多少用户完成的，在不同的维度下表现如何”。它的设计思想，就是把“行为”和“行为的主体”作为分析对象，通过灵活的维度筛选和分组，来洞察这些行为的发生规律。</p><p>在产品设计上，用户首先选择一个或者多个事件，例如“查看商品详情”这个事件。然后选择指标，是总次数，还是触发用户数，还是人均次数。接下来选择维度进行分组，例如按设备类型分组，就可以看到 iOS 和 Android 用户分别的表现。再选择筛选条件，例如筛选出来自北京的用户。最后选择时间范围和时间粒度，例如查看最近 30 天，按天展示。</p><p>这样的产品抽象，把原本复杂的 SQL 查询，转化为用户可以自主配置的几个简单选项。而在后台，这些配置会被翻译成对 Event 表和 User 表的关联查询。</p><p>事件分析在语义上，是跟 MDX 等价的。</p><p>再来看漏斗分析模型的产品抽象思想。</p><p>漏斗分析解决的核心问题是——“一个业务流程的各个环节，分别有多少用户完成，转化率是多少，在哪个环节流失最严重”。它的设计思想，就是把用户的行为序列抽象成一个有先后顺序的步骤链条，分析用户在这个链条上的完成情况。</p><p>在产品设计上，用户定义一个漏斗的多个步骤，例如第一步是“浏览首页”，第二步是“点击商品”，第三步是“加入购物车”，第四步是“提交订单”。然后设置转化窗口期，例如 7 天内，也就是说用户在浏览首页后的 7 天内完成后续步骤，才算转化成功。再选择筛选条件和时间范围。</p><p>这样的产品抽象，把业务流程分析的需求，转化为用户可以自主定义的漏斗步骤。而在后台，系统需要对每个用户的事件序列进行分析，判断这个用户是否在规定的时间窗口内，按顺序完成了这些步骤。</p><p>因为要做时序分析，漏斗分析在语义上，是超过了 MDX 的表述能力。而为了提升性能，规避Join 操作，通常需要使用时间窗口函数以及自定义 UDF，对 Event 表做分析。例如，使用LEAD 或者 LAG 函数，判断用户的下一个事件是否符合漏斗的下一步要求，并且时间戳在转化窗口期内。</p><p>这两个分析模型在具体实现上，还有很多细节。例如，漏斗分析是以用户为粒度，还是以用户的一次 session 为粒度等等，这里就不再展开了，大家如果有兴趣，欢迎留言，或者查看神策分析的相关公开资料。</p><p>上面所描述的产品抽象，都遵循了同样的设计理念，就是把业务分析人员最常用的分析范式，通过界面配置的方式暴露出来，而把复杂的 SQL 编写和性能优化隐藏在后台。这样，分析师不需要懂 SQL，也不需要理解底层的表结构，就可以快速完成分析，大大降低了数据使用的门槛。</p><p>和 BI 系统中主要使用 SQL 来完成查询的方式相比，在用户行为分析产品中使用特化的分析模型，除了上面描述的降低使用门槛的好处以外，还有其它的一些好处：</p><p>首先，这些分析模型的查询最终也会翻译成特定的 SQL+UDF 来在 Doris 中执行，那么，我们就可以针对性地对这些 SQL 进行性能优化，从而避免了单个用户写出不优雅的 SQL，浪费计算资源。</p><p>其次，因为分析的范式被分析模型限定了，查出来的数据的范式也是确定的，因此可以数据可视化方面也可以进行针对性的设计和优化。</p><p>第三，产品化查询界面而不是直接让使用者写 SQL，对于权限控制、隐私控制、加密等，都更加方便与可控。</p><p>从我们日常的实践中，常用的分析模型，基本可以覆盖使用者绝大部分的分析需求。对于没有覆盖的部分分析需求，可以保留直接提交 SQL 作为兜底。在真实的日常场景中，大家也不用局限在上面列出的有限的分析模型中，可以把自己组织内经常使用的查询范式也抽象成分析模型。</p><h2 id="曾经踩过的坑" tabindex="-1">曾经踩过的坑 <a class="header-anchor" href="#曾经踩过的坑" aria-label="Permalink to &quot;曾经踩过的坑&quot;">​</a></h2><p>刚才我们介绍了用户行为分析系统的架构设计和产品抽象，接下来，我会跟大家分享一下，在过去十年的经验中，我碰到的一些常见问题以及解决办法。</p><h3 id="流量突增与数据积压的处理策略" tabindex="-1">流量突增与数据积压的处理策略 <a class="header-anchor" href="#流量突增与数据积压的处理策略" aria-label="Permalink to &quot;流量突增与数据积压的处理策略&quot;">​</a></h3><p>在实际运营中，流量突增是我们经常会遇到的问题。可能是因为一次成功的营销活动，可能是某个产品功能突然火爆，也可能是重大节假日带来的自然流量增长。面对这种情况，数据积压该怎么办呢？</p><p>首先，我们需要理解，在整个数据链路中，不同环节对流量突增的承受能力是不同的。</p><p>从数据接收层面来看，Fluentd 的性能是非常好的，而且处理逻辑比较简单，很少会成为瓶颈。即使真的遇到 Fluentd 处理不过来的极端情况，数据也不会丢失，而是会积压在客户端SDK 的本地缓存中。SDK 碰到网络不可用或者服务端响应慢的时候，数据会先在本地排队，等待后续重试上传。这是第一道保护屏障。</p><p>大部分情况下，数据积压主要发生在 Kafka 和后续的 Loader 环节。这是因为，虽然 Kafka 的吞吐能力很强，但如果下游的 Loader 消费速度，也就是 ETL 或者 Doris 的写入能力跟不上，数据就会堆积在 Kafka 的 Topic 中。这种积压的好处是，数据只会延迟，不会丢失。Kafka 会把所有的消息持久化到磁盘上，只要磁盘空间足够，数据就会一直保存着。</p><p>那么，面对这种积压，我们应该采取什么策略呢？</p><p>这需要分情况讨论。</p><p>如果是每天短暂的突发性流量增长，则可以容忍必要的延迟。高峰过后，流量回落，Loader就有机会把积压的数据慢慢处理掉。</p><p>而如果是确定性的、长期的流量增加，那就可以在预算允许的范围内扩容了。Kafka 和Loader 从设计上都是非常易于横向扩容的。值得注意的是，在扩容之前，我们还可以做一些优化工作。比如，检查 Loader 的代码逻辑，看看是否有性能瓶颈；检查 Doris 的写入配置，看看是否可以通过调整批次大小、并发度等参数来提升写入速度。</p><p>另外，对于流量突增的监控和告警也非常重要。我们需要实时监控整个数据流的延迟情况，一旦发现延迟超过预设的阈值，就应该及时告警，让运维人员能够第一时间介入处理。这样可以避免小问题演变成大故障。这部分在第 17 节课也有讨论。</p><h3 id="查询积压" tabindex="-1">查询积压 <a class="header-anchor" href="#查询积压" aria-label="Permalink to &quot;查询积压&quot;">​</a></h3><p>由于用户行为分析主要侧重的还是查询能力，查询并发响应能力一般。因此，当比较多人同时提交查询，特别是其中有扫描数据量很大的大查询时，查询积压就很容易发生。同时，用户行为分析产品为了提供报表能力，也会有例行调度任务，这些都会增加查询的积压。</p><p>针对查询积压的问题，我们可以从几个不同的层面来采取应对措施。</p><p>第一，资源分队列隔离。</p><p>这个策略在第 16 节课中有详细介绍。核心思想是，把不同人的不同类型的查询放到不同的资源队列中执行，互相隔离，避免一类查询占满所有资源，导致其他查询完全无法执行。</p><p>第二，前端优化排队机制。</p><p>在产品的前端界面上，我们也可以做一些优化，来改善用户在查询积压时的体验。</p><p>最直接的方式，就是在前端实现一个查询排队机制。当后端已经积压时，新的查询请求不是直接提交，而是先在应用层排队。并显示当前的排队位置和预计的等待时间，让用户心里有数。</p><p>等到前面的查询执行完毕，有资源空闲出来之后，再把排队的查询逐个提交到后端执行。</p><p>这样做一方面缓解了后端压力，一方面也让用户能够清楚地看到自己的查询状态，对于用户体验的提升是非常明显的。</p><p>第三，查询缓存机制。</p><p>在用户行为分析系统中，很多查询其实是重复的。例如，多个用户可能都会查看同一个时间范围内的相同指标，或者同一个用户可能在短时间内反复查看同一个分析结果。如果每次都重新执行一遍查询，就会造成大量的重复计算，浪费资源。</p><p>所以需要引入缓存，把查询条件和结果保存起来。后续如果有相同的查询请求，就直接从缓存中返回结果，而不需要再次查询数据库。</p><p>在缓存策略上，首先可以利用 Doris 自带的 SQL 级别缓存。其次则是在应用层实现更精细粒度的缓存。我们可以使用 Redis 这样的内存数据库，根据业务逻辑自定义缓存的 key 和粒度。例如，刚进行的一次过去 30 天的查询，除了整个 SQL 进行缓存之外，我们还可以把每一天的查询结果保存下来，这样再查询过去 15 天的数据时也能利用上。</p><p>需要注意的是，由于缓存会导致新入库的数据在部分查询中无法体现，因此对于实时性要求高的查询，可以设置较短的缓存时间。而对于历史数据的统计分析，则可以设置较长的缓存时间。</p><p>第四，产品层面对于大查询的限制。</p><p>我们还需要从产品设计的角度，对一些不合理的大查询进行限制，从源头上减少查询积压的发生。</p><p>具体来说，可以限制用户单次查询的时间范围。如果需要查询更长时间范围的数据，引导用户使用报表功能，通过离线调度的方式来完成。</p><p>另外，还可以限制查询返回的数据量。例如，对于明细数据的展示，限制单次最多只能出 10万条记录。如果需要更多数据，可以提供异步导出的功能，把大查询放到后台慢慢执行。</p><p>这些限制措施，需要在产品设计的时候就考虑清楚，在界面上给出明确的提示和说明，让用户理解为什么会有这样的限制，以及如果有特殊需求应该怎么办。</p><h3 id="国际化的应对" tabindex="-1">国际化的应对 <a class="header-anchor" href="#国际化的应对" aria-label="Permalink to &quot;国际化的应对&quot;">​</a></h3><p>当我们的用户分布在不同的国家地区时，用户行为分析产品本身也要解决相应的国家化问题。这里面核心就是多时区和币种的问题，我在第 13 节课做过详细描述。</p><p>简单来说，对于时区问题，我们需要将所有时间统一为 UTC 时区存储，但同时要保留原始的时区信息作为一个单独的字段。这样，在后续的分析和展示时，就可以根据用户所在的时区，将 UTC 时间转换回本地时间，保证分析结果的准确性。例如，对于一个跨国电商平台，美国分析师和中国分析师看到的“昨天”，虽然时间范围不同，但都应该准确对应各自时区的昨天。</p><p>对于货币问题，则一般需要在 ETL 时候按照当时的汇率进行统一换算。但同时，原始的币值和币种信息也需要保留下来，因为在某些分析场景下，可能需要按照查询发生时候的汇率重新进行换算。</p><p>这些国际化的处理，虽然增加了一定的复杂度，但对于服务全球用户的产品来说是必不可少的。</p><h2 id="局限" tabindex="-1">局限 <a class="header-anchor" href="#局限" aria-label="Permalink to &quot;局限&quot;">​</a></h2><p>在探讨系统实现和产品抽象之后，我们也需要意识到它的局限。</p><p>首先，我们所有的设计都是为了满足内部使用者的临时性分析的，以分析的灵活性为主要设计目标，哪怕进行了各种优化，系统能够响应的 QPS 依然是非常有限的，依然是不能让外部用户直接来查询的。如果是想在 App 上展示类似于榜单之类的数据，可以在系统中查询好再导出到特定的存储中。</p><p>其次，整个数据流的设计上虽然已经尽量保证了数据的完整性，但由于客户端采集数据的天然缺陷，我们很难保证 100% 的数据一致性，因此，这一系统计算出来的指标，通常只用于洞察和决策，而不应作为要求最严格的财务指标计算。</p><h2 id="总结与启发" tabindex="-1">总结与启发 <a class="header-anchor" href="#总结与启发" aria-label="Permalink to &quot;总结与启发&quot;">​</a></h2><p>在这节课中，我们顺着数据分析这条线路，继 BI 之后，学习了如何在一个特定的分析领域，开发特化的分析产品，更好地服务实际的业务。</p><p>这节课中描述的用户行为分析系统构建方法，其实具有很强的通用性。你在设计其它的分析系统时，比如商品分析、素材分析，都可以参考这一设计范式，只是在分析模型和数据模型的抽象上会有所不同。</p><p>通过这节课程的学习，对于数据产品经理或者数据开发工程师，希望能帮你了解应该如何从零开始开发一个用户行为产品。对于其它领域的产品经理和数据分析师，则可以从使用者的视角出发，熟悉用户行为分析产品有哪些应用场景和业务价值。而且搞清楚这类系统的实现原理，也有助于使用者了解系统的局限，更好地使用系统。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ul><li><p>在你所从事的业务领域，用户行为分析重要吗？你们现在有充分地进行用户行为分析吗？</p></li><li><p>除了用户行为分析，你觉得还有哪些特定的分析需求可以做类似的抽象与专门处理呢？</p></li></ul><p>期待你在留言区分享你的思考。对于系统中的一些具体实现细节，如果希望有更深入的了解，也欢迎留言与我直接交流，也欢迎你把这节课分享给其他人。如果这节课对你有启发，也欢迎分享给身边更多朋友！</p>`,124)])])}const g=a(n,[["render",s]]);export{u as __pageData,g as default};
